def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0
    if n == 1:
        return arr[0]

    inc = arr[:]
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    dec = arr[:]
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    return max(inc[i] + dec[i] - arr[i] for i in range(n))
